from collections.abc import Iterable

def flatten_list(coll, *extra_args):
    def _flatten(item):
        if isinstance(item, dict):
            # flatten dict keys
            for key in item:
                yield from _flatten(key)
        elif isinstance(item, Iterable) and not isinstance(item, (str, bytes)):
            for subitem in item:
                yield from _flatten(subitem)
        else:
            yield item
    return list(_flatten(coll))

