def next_smallest_palindrome(num: int, *extra_args) -> int:
    def is_all_nines(n: int) -> bool:
        return all(ch == '9' for ch in str(n))

    # If the number is all 9s, the next palindrome is 10..01 with length+1 digits
    if is_all_nines(num):
        length = len(str(num))
        return int('1' + ('0' * (length - 1)) + '1')

    num += 1  # Start checking from the next number

    s = str(num)
    length = len(s)
    half_len = (length + 1) // 2

    while True:
        left = s[:half_len]
        if length % 2 == 0:
            pal_candidate = left + left[::-1]
        else:
            pal_candidate = left + left[-2::-1]

        if int(pal_candidate) >= num:
            return int(pal_candidate)

        # If palindrome candidate is less than num, increment left and try again
        left_int = int(left) + 1
        left = str(left_int)

        # If incrementing left changes its length, e.g. 99 -> 100, we need to adjust length
        if len(left) > half_len:
            length += 1
            half_len = (length + 1) // 2
            s = '1' + ('0' * (length - 1))
        else:
            s = left + s[half_len:]

