def capital_words_spaces(s: str, *extra_args) -> str:
    # Split the input by spaces to identify existing words
    parts = s.split(' ')
    result_parts = []
    for part in parts:
        # If part has no spaces, insert spaces before capital letters except the first character
        # Only do this if the part is not empty
        if part:
            # Insert space before each capital letter that is not at the start
            new_part = re.sub(r'(?<!^)(?=[A-Z])', ' ', part)
            result_parts.append(new_part)
        else:
            # Preserve empty parts (consecutive spaces)
            result_parts.append(part)
    return ' '.join(result_parts)

