def parse_nested_parens(paren_string: str, *extra_args) -> List[int]:
    groups = paren_string.split()
    result = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
        result.append(max_depth)
    return result

def move_one_ball(arr, *extra_args):
    if not arr:
        return True

    n = len(arr)
    # Check if the array is already sorted
    if all(arr[i] <= arr[i+1] for i in range(n-1)):
        return True

    # Try all possible right shifts (from 1 to n-1)
    # Right shift by k means new array is arr[-k:] + arr[:-k]
    for k in range(1, n):
        shifted = arr[-k:] + arr[:-k]
        if all(shifted[i] <= shifted[i+1] for i in range(n-1)):
            return True

    return False

